insert into public.quiz_questions (mode, step, question, options, correct, explanation)
values
('island', 1, 'Wie heißt die Hauptstadt von Gran Canaria?', '["Las Palmas de Gran Canaria", "Maspalomas", "Santa Cruz de Tenerife", "Telde"]'::jsonb, 0, 'Las Palmas de Gran Canaria, kurz „Las Palmas“, liegt im Nordosten der Insel.'),
('island', 1, 'Zu welchem Land gehören die Kanaren?', '["Portugal", "Spanien", "Frankreich", "Marokko"]'::jsonb, 1, 'Spanien – die Kanaren sind eine autonome Gemeinschaft mit eigener Regierung in Santa Cruz de Tenerife und Las Palmas.'),
('island', 1, 'Welche Sprache spricht man auf Gran Canaria?', '["Portugiesisch", "Italienisch", "Spanisch", "Französisch"]'::jsonb, 2, 'Spanisch, genauer der kanarische Dialekt – man duzt hier traditionell auch Fremde, das „tú“ ist normal.'),
('island', 1, 'Welche Währung gilt auf den Kanaren?', '["Peseta", "Kanarische Krone", "Dollar", "Euro"]'::jsonb, 3, 'Euro. Die Kanaren sind EU-Gebiet, aber nicht im Zollgebiet der EU.'),
('island', 1, 'Wie heißt der berühmte Fels im Inselinneren?', '["Roque Nublo", "El Teide", "Dedo de Dios", "Montserrat"]'::jsonb, 0, 'Der Roque Nublo ist das Wahrzeichen der Insel – ein 80 Meter hoher Basaltfelsen auf 1.813 Metern.'),
('island', 1, 'Wie heißt die Nachbarinsel westlich von Gran Canaria?', '["Lanzarote", "Teneriffa", "Fuerteventura", "La Gomera"]'::jsonb, 1, 'Teneriffa mit dem Teide (3.718 m). Fuerteventura liegt im Osten.'),
('island', 1, 'Wo liegt Gran Canaria?', '["Mittelmeer", "Vor Portugal", "Vor der Küste Marokkos", "Karibik"]'::jsonb, 2, 'Rund 210 Kilometer westlich der marokkanischen Küste, auf der Afrikanischen Platte.'),
('island', 1, 'Wie heißen die großen Dünen im Süden?', '["Dünen von las Canteras", "Dünen von Arinaga", "Dünen von Amadores", "Dünen von Maspalomas"]'::jsonb, 3, 'Die Dünen von Maspalomas sind Naturschutzgebiet und wandern mit dem Wind langsam weiter.'),
('island', 1, 'Was sind „papas arrugadas“?', '["In Salzwasser gekochte Kartoffeln", "Frittierte Fischstücke", "Gefüllte Paprika", "Ein Käse"]'::jsonb, 0, 'Kleine Kartoffeln, in sehr salzigem Wasser gekocht – die Schale runzelt (daher der Name).'),
('island', 1, 'Wie kommt man am schnellsten nach Teneriffa?', '["Mit dem Zug", "Mit der Fähre", "Über den Flughafen nur mit Umweg", "Mit der Seilbahn"]'::jsonb, 1, 'Fähre ab Agaete (Fred. Olsen) oder ab Las Palmas, rund 80 Minuten.'),
('island', 1, 'Womit fährt man auf der Insel am besten ins Bergdorf?', '["Mit der Bahn", "Nur mit dem Taxi", "Mit dem Bus oder Auto", "Nur zu Fuß"]'::jsonb, 2, 'Ein Zug auf die Insel existiert bis heute nicht; Busse heißen hier „guaguas“.'),
('island', 1, 'Welche Farbe hat der Sand in den Dünen von Maspalomas?', '["Schwarz", "Weiß", "Rot", "Goldbraun"]'::jsonb, 3, 'Goldbrauner Sand, der von den Passatwinden aus der Sahara und vom Strand herangetragen wird.'),
('island', 2, 'Wie viele große Inseln gehören zu den Kanaren?', '["7", "6", "5", "9"]'::jsonb, 0, 'Sieben große: El Hierro, La Palma, La Gomera, Teneriffa, Gran Canaria, Fuerteventura und Lanzarote. La Graciosa ist seit 2018 die achte bewohnte.'),
('island', 2, 'Welcher Berg ist der höchste Spaniens?', '["Roque Nublo", "Teide", "Mulhacén", "Pico de las Nieves"]'::jsonb, 1, 'Der Teide auf Teneriffa mit 3.718 Metern – auch der höchste Berg auf spanischem Boden.'),
('island', 2, 'Wie heißt die rundliche Form der Insel auf der Karte?', '["Lang und schmal", "Dreieckig", "Fast kreisförmig", "Herzförmig"]'::jsonb, 2, 'Gran Canaria ist fast kreisrund, rund 50 Kilometer im Durchmesser.'),
('island', 2, 'Wie heißen die tiefen Trockentäler der Insel?', '["Ramblas", "Valles", "Calderas", "Barrancos"]'::jsonb, 3, 'Barrancos. Bei seltenem Starkregen führen sie reißende Sturzbäche.'),
('island', 2, 'Was ist „gofio“?', '["Geröstetes Getreidemehl", "Ein Käse", "Ein Fischgericht", "Ein Wein"]'::jsonb, 0, 'Gofio war das Grundnahrungsmittel der Inselbewohner – geröstetes, gemahlenes Getreide, heute in Milch oder Eintopf.'),
('island', 2, 'Wie heißen die Saucen zu den Kartoffeln?', '["Salsas", "Mojos", "Aliolis", "Chimichurris"]'::jsonb, 1, 'Mojo rojo (scharf, rot) und Mojo verde (grün, mit Koriander).'),
('island', 2, 'In welchem Ort steht das Wahrzeichen mit den zwei Felsenbuchten im Norden?', '["Puerto de Mogán", "Agaete", "Las Palmas", "Arucas"]'::jsonb, 2, 'Die Playa de las Canteras in Las Palmas gilt als eine der besten Stadtstrände Europas.'),
('island', 2, 'Welche Frucht wird auf der Insel in großen Mengen angebaut?', '["Äpfel", "Datteln", "Kirschen", "Bananen"]'::jsonb, 3, '„Plátano de Canarias“ – die kleinen, aromatischen Bananen mit geschützter Herkunftsbezeichnung.'),
('island', 2, 'Wie heißt der größte Hafen der Insel?', '["Puerto de la Luz", "Puerto Rico", "Arinaga", "Mogán"]'::jsonb, 0, 'Der Puerto de la Luz in Las Palmas – einer der wichtigsten Atlantikhäfen mit riesigem Umschlag.'),
('island', 2, 'Was bedeutet „calima“?', '["Ein Regenguss", "Saharastaub in der Luft", "Ein Erdbeben", "Ein Brand"]'::jsonb, 1, 'Heißer Wind aus der Sahara mit Staub – die Sicht wird milchig, die Temperatur steigt deutlich.'),
('island', 2, 'Welche Stadt liegt im Nordwesten und ist für ihre Kirche bekannt?', '["Agüimes", "Mogán", "Teror", "Fataga"]'::jsonb, 2, 'Teror mit der Basilika Nuestra Señora del Pino – die Schutzpatronin der Insel.'),
('island', 2, 'Wie heißt der Ort mit den berühmten Höhlenwohnungen im Süden?', '["Temisas", "Tejeda", "Artenara", "Guayadeque"]'::jsonb, 3, 'Im Barranco de Guayadeque liegen Wohnhöhlen und Restaurants direkt im Fels.'),
('island', 3, 'Welcher ist der höchste Berg der Insel?', '["Morro de la Agujereada", "Pico de las Nieves", "Roque Nublo", "Teide"]'::jsonb, 0, 'Der Morro de la Agujereada mit 1.956 Metern – der Pico de las Nieves daneben ist mit 1.949 Metern der zweithöchste.'),
('island', 3, 'Wie groß ist Gran Canaria?', '["620 km²", "1.560 km²", "2.400 km²", "3.000 km²"]'::jsonb, 1, '1.560 km² – damit die drittgrößte der Kanaren nach Teneriffa und Fuerteventura.'),
('island', 3, 'Wie viele Einwohner hat die Insel etwa?', '["180.000", "430.000", "860.000", "1,5 Mio."]'::jsonb, 2, 'Rund 864.000 (2024) – davon etwa die Hälfte in Las Palmas und Umgebung.'),
('island', 3, 'Was bedeutet der Name „Las Palmas“ wörtlich?', '["Die Strände", "Die Häfen", "Die Dünen", "Die Palmen"]'::jsonb, 3, 'Palmen. Der vollständige Name lautet Las Palmas de Gran Canaria.'),
('island', 3, 'Welches Tier ist auf der Insel weit verbreitet und endemisch?', '["Die Kanareneidechse", "Der Luchs", "Das Murmeltier", "Der Igel"]'::jsonb, 0, 'Gallotia stehlini, die Kanareneidechse – sie sonnt sich auf Mauern und Steinen.'),
('island', 3, 'Wie heißt der Vulkankrater nahe Las Palmas?', '["Caldera de Taburiente", "Caldera de Bandama", "Caldera de Tejeda", "Krater von Fataga"]'::jsonb, 1, 'Die Caldera de Bandama – rund 1.000 Meter im Durchmesser und 200 Meter tief.'),
('island', 3, 'Was ist der „Roque“ in Ortsnamen wie Roque Nublo?', '["Ein Wald", "Ein Bach", "Ein Fels", "Ein Dorf"]'::jsonb, 2, 'Roque heißt Fels – im Kanarischen sind es oft Basaltfelsen oder Felskegel.'),
('island', 3, 'Wie heißt der Flughafen der Insel?', '["Teneriffa Nord", "Las Palmas Sur", "Maspalomas", "Gran Canaria"]'::jsonb, 3, 'Flughafen Gran Canaria, Kürzel LPA, in der Bucht von Gando.'),
('island', 3, 'Wann blühen die Mandelbäume im Inselinneren?', '["Im Februar", "Im Juli", "Im Mai", "Im Oktober"]'::jsonb, 0, 'Rund um Tejeda im Februar – dann feiert man dort das Mandelblütenfest.'),
('island', 3, 'Welche Bäume prägen die Bergwälder?', '["Eichen", "Kanarische Kiefern", "Buchen", "Birken"]'::jsonb, 1, 'Pinus canariensis – sehr feuerfest, treibt nach Bränden aus dem Stamm wieder aus.'),
('island', 3, 'Was ist eine „guagua“?', '["Ein Boot", "Ein Kuchen", "Der Bus", "Ein Lied"]'::jsonb, 2, 'Das kanarische Wort für Bus – stammt vermutlich aus dem Kubanischen.'),
('island', 3, 'Wie heißt der Ort mit der berühmten Rum-Brennerei?', '["San Mateo", "Agaete", "Santa Brígida", "Arucas"]'::jsonb, 3, 'Arucas – dort steht die Brennerei Arehucas und die neugotische Kirche San Juan Bautista.'),
('island', 4, 'Wie tief ist die Caldera de Bandama?', '["200 m", "80 m", "450 m", "700 m"]'::jsonb, 0, 'Rund 200 Meter tief, 1.000 Meter breit. Der Pico de Bandama daneben ist 569 Meter hoch.'),
('island', 4, 'Welche Insel liegt östlich von Gran Canaria?', '["La Palma", "Fuerteventura", "El Hierro", "La Gomera"]'::jsonb, 1, 'Fuerteventura – man sieht sie an klaren Tagen von den Höhen aus.'),
('island', 4, 'Was ist ein „barranco“?', '["Ein Strand", "Ein Marktplatz", "Ein Trockental", "Ein Gipfel"]'::jsonb, 2, 'Ein von Wasser geformtes Tal; viele führen nur bei Starkregen Wasser.'),
('island', 4, 'Wie heißt die alte Altstadt von Las Palmas?', '["Triana", "Arenales", "Guanarteme", "Vegueta"]'::jsonb, 3, 'Vegueta – der Gründungsort von 1478 mit Kathedrale Santa Ana und Casa de Colón.'),
('island', 4, 'Was wird in Temisas angebaut?', '["Oliven", "Wein", "Kaffee", "Baumwolle"]'::jsonb, 0, 'Im Tal von Temisas liegt der größte Olivenhain des Archipels; das Öl heißt „Caserío de Temisas“.'),
('island', 4, 'Auf welcher Höhe liegt Temisas?', '["Etwa 350 m", "Etwa 690 m", "Etwa 1.100 m", "Etwa 1.800 m"]'::jsonb, 1, 'Rund 687 Meter – deshalb ist es dort oben oft einige Grad kühler als an der Küste.'),
('island', 4, 'Welche Stadt liegt am Meer und ist für ihren Fischerhafen bekannt?', '["Tejeda", "Artenara", "Mogán", "San Bartolomé"]'::jsonb, 2, 'Puerto de Mogán im Südwesten – kleine Kanäle, Boote und ein Hafen.'),
('island', 4, 'Was ist „aloe vera“ auf der Insel?', '["Ein Wein", "Ein Vulkan", "Ein Fisch", "Eine Heilpflanze"]'::jsonb, 3, 'Aloe wird auf Gran Canaria großflächig angebaut und zu Kosmetik und Saft verarbeitet.'),
('island', 4, 'Wie heißt die Hochebene um Tejeda?', '["Caldera de Tejeda", "Valle de Agaete", "Llanos de Maspalomas", "Meseta de Fataga"]'::jsonb, 0, 'Die Caldera de Tejeda ist ein eingebrochener Vulkan mit rund 15 Kilometer Durchmesser.'),
('island', 4, 'Welche Farbe hat der kanarische Mojo verde?', '["Rot", "Grün", "Gelb", "Schwarz"]'::jsonb, 1, 'Grün vom Koriander (oder Petersilie); Mojo rojo wird mit getrockneten Chilis gemacht.'),
('island', 4, 'Wann ist der höchste Feiertag der Kanaren?', '["12. Oktober", "1. Januar", "30. Mai", "1. Mai"]'::jsonb, 2, 'Der 30. Mai ist „Día de Canarias“ – Feiertag auf allen Inseln.'),
('island', 4, 'Wie heißt das Dorf im Süden mit Palmen im Tal?', '["Firgas", "Artenara", "Teror", "Fataga"]'::jsonb, 3, 'Fataga liegt in einem Palmental an der Straße von Maspalomas ins Bergland.'),
('island', 5, 'Welchen Berg sieht man bei klarer Sicht am Horizont?', '["Den Teide auf Teneriffa", "Fuerteventuras Vulkane", "Die Berge von La Gomera", "Madeiras Gipfel"]'::jsonb, 0, 'Vom Pico de las Nieves aus ist der Teide bei klarer Luft am Horizont zu erkennen – 60 km entfernt.'),
('island', 5, 'Wie alt ist die Insel geologisch ungefähr?', '["1,5 Mio. Jahre", "14,5 Mio. Jahre", "80 Mio. Jahre", "300 Mio. Jahre"]'::jsonb, 1, 'Rund 14,5 Millionen Jahre – die ältesten Gesteine liegen im Südwesten.'),
('island', 5, 'Wann brach der letzte Vulkan auf der Insel aus?', '["Vor 20.000 Jahren", "Vor 200 Jahren", "Vor 2.000 Jahren", "Er ist noch aktiv"]'::jsonb, 2, 'Die letzte Eruption war die von Bandama vor rund 2.000 Jahren.'),
('island', 5, 'Wie hoch ist der Roque Nublo?', '["1.200 m", "1.600 m", "2.100 m", "1.813 m"]'::jsonb, 3, 'Der Gipfel liegt auf 1.813 Metern; der Fels selbst ragt etwa 80 Meter aus dem Sattel.'),
('island', 5, 'Welche Pflanze liefert den roten Farbstoff, mit dem die Insel früher handelte?', '["Koschenille", "Indigo", "Krapp", "Safran"]'::jsonb, 0, 'Die Cochenille-Schildlaus auf Feigenkakteen – im 19. Jahrhundert wichtigster Export.'),
('island', 5, 'Wie heißt das Schutzgebiet im Südwesten mit Kiefernwald?', '["Tamadaba", "Alle drei", "Pilancones", "Inagua"]'::jsonb, 1, 'Alle drei sind Naturparks im Südwesten; zusammen bilden sie einen großen Waldgürtel.'),
('island', 5, 'Was ist ein „mirador“?', '["Ein Brunnen", "Ein Hotel", "Ein Aussichtspunkt", "Ein Parkplatz"]'::jsonb, 2, 'Aussichtspunkt – an der Straße ins Gebirge gibt es viele davon.'),
('island', 5, 'Welches Meer umgibt die Insel?', '["Mittelmeer", "Nordsee", "Rotes Meer", "Atlantik"]'::jsonb, 3, 'Atlantik – mit Passatwinden, die den Norden feucht und den Süden trocken machen.'),
('island', 5, 'Warum ist der Norden grüner als der Süden?', '["Passatwolken regnen dort ab", "Mehr Flüsse", "Mehr Bewässerung", "Höhere Lage"]'::jsonb, 0, 'Die Passatwinde stauen sich an den Bergen, der Norden bekommt Nebel und Regen, der Süden bleibt trocken.'),
('island', 5, 'Wie heißt der Ort mit den Kanälen und dem kleinen Strand im Südwesten?', '["Puerto Rico", "Puerto de Mogán", "Arguineguín", "Playa del Cura"]'::jsonb, 1, 'Puerto de Mogán – „Klein-Venedig“ genannt, mit Kanälen und Fischerbooten.'),
('island', 5, 'Welcher Käse ist auf den Kanaren typisch?', '["Gouda", "Parmesan", "Queso de flor", "Feta"]'::jsonb, 2, 'Queso de flor – mit der Blüte der Artischockendistel hergestellt, auf Gran Canaria eine Spezialität.'),
('island', 5, 'Wie heißt der höchste Ort der Insel?', '["San Mateo", "Tejeda", "Temisas", "Artenara"]'::jsonb, 3, 'Artenara liegt auf rund 1.270 Metern – viele Häuser sind in den Fels gebaut.'),
('island', 6, 'Wer gründete 1478 die Stadt Las Palmas?', '["Juan Rejón", "Pedro de Vera", "Fernando Guanarteme", "Christoph Kolumbus"]'::jsonb, 0, 'Juan Rejón landete am 24. Juni 1478 an der Mündung des Barranco de Guiniguada – dort liegt heute Vegueta.'),
('island', 6, 'In welchem Jahr war die Eroberung der Insel abgeschlossen?', '["1478", "1483", "1492", "1502"]'::jsonb, 1, 'Pedro de Vera unterwarf 1483 die letzten Widerstandsnester bei Gáldar.'),
('island', 6, 'Wie nennt man die Ureinwohner Gran Canarias?', '["Guanches", "Bimbaches", "Canarios", "Arucas"]'::jsonb, 2, 'Canarios – „Guanches“ sind die Ureinwohner Teneriffas. Die Bezeichnungen werden oft verwechselt.'),
('island', 6, 'Wie heißt die bemalte Höhle bei Gáldar?', '["Cueva de los Verdes", "Cueva del Rey", "Cueva de Guayadeque", "Cueva Pintada"]'::jsonb, 3, 'Die Cueva Pintada ist für ihre geometrischen Wandmalereien berühmt und heute Museum.'),
('island', 6, 'Welches Haus in Las Palmas erinnert an Kolumbus?', '["Casa de Colón", "Casa de Vera", "Palacio Episcopal", "Casa de la Cultura"]'::jsonb, 0, 'Kolumbus stoppte 1492 auf dem Weg nach Amerika, um das Ruder der „Pinta“ reparieren zu lassen.'),
('island', 6, 'Welche Kirche steht im Zentrum von Vegueta?', '["San Juan Bautista", "Kathedrale Santa Ana", "Basílica del Pino", "Iglesia de San Telmo"]'::jsonb, 1, 'Die Kathedrale Santa Ana – 1497 begonnen und über Jahrhunderte weitergebaut.'),
('island', 6, 'Wie viele Gemeinden hat Gran Canaria?', '["14", "18", "21", "27"]'::jsonb, 2, '21 Municipios – Temisas gehört zur Gemeinde Agüimes.'),
('island', 6, 'Wie heißt die Autobahn entlang der Ostküste?', '["A-7", "TF-1", "GC-60", "GC-1"]'::jsonb, 3, 'Die GC-1 führt von Las Palmas über den Flughafen bis nach Mogán.'),
('island', 6, 'Was ist ein „almogarén“?', '["Eine Kultstätte der Ureinwohner", "Ein Bauernhaus", "Ein Hafen", "Eine Zisterne"]'::jsonb, 0, 'Heilige Stätten unter freiem Himmel – der Roque Bentayga ist die bekannteste.'),
('island', 6, 'Welches Getränk wird aus Zuckerrohr gebrannt?', '["Wein", "Rum", "Bier", "Cidre"]'::jsonb, 1, 'Rum – die Brennerei Arehucas in Arucas ist die bekannteste der Kanaren.'),
('island', 6, 'Woher kam die Kartoffel, die hier „papa“ heißt?', '["Aus Afrika", "Aus Asien", "Aus Südamerika", "Aus Europa"]'::jsonb, 2, 'Ursprünglich aus den Anden; über die spanischen Kolonien kam sie auf die Inseln und nach Europa.'),
('island', 6, 'Welches Fest ist das größte in Las Palmas?', '["Die Semana Santa", "Das Mandelblütenfest", "Das Erntedankfest", "Der Karneval"]'::jsonb, 3, 'Der Karneval von Las Palmas zählt zu den größten Spaniens – mit der berühmten Drag-Queen-Gala.'),
('island', 7, 'Seit wann ist Gran Canaria UNESCO-Biosphärenreservat?', '["2005", "1995", "2013", "2019"]'::jsonb, 0, 'Seit 2005 – rund 43 Prozent der Inselfläche gehören dazu, plus ein großer Meeresstreifen.'),
('island', 7, 'Wie viel Prozent der Inselfläche sind Biosphärenreservat?', '["23 %", "43 %", "33 %", "63 %"]'::jsonb, 1, '43 Prozent – der Südwesten mit Tamadaba, Inagua, Pilancones und der Caldera de Tejeda.'),
('island', 7, 'Wer ist die Schutzpatronin der Insel?', '["Virgen del Carmen", "Santa Ana", "Virgen del Pino", "Santa Lucía"]'::jsonb, 2, 'Die Jungfrau vom Pinienbaum in Teror; ihr Fest ist am 8. September.'),
('island', 7, 'Woher stammen die Ureinwohner der Insel?', '["Aus Skandinavien", "Aus Griechenland", "Aus Südamerika", "Von den Berbern Nordafrikas"]'::jsonb, 3, 'Berber vom Beginn unserer Zeitrechnung – Inschriften in libysch-berberischer Schrift belegen es.'),
('island', 7, 'Welcher Widerstandskämpfer der Canarios ist legendär?', '["Doramas", "Guanarteme", "Tenesor", "Bentayga"]'::jsonb, 0, 'Doramas führte den Guerillakampf in den Wäldern – heute nach ihm benannt: das Dorf Doramas und der Parque Doramas.'),
('island', 7, 'Wer war der letzte Herrscher, der sich taufen ließ und Frieden schloss?', '["Doramas", "Fernando Guanarteme", "Pedro de Vera", "Juan Rejón"]'::jsonb, 1, 'Tenesor Semidán, getauft als Fernando Guanarteme – er verhandelte 1483 die Übergabe.'),
('island', 7, 'Welcher Dichter und Schriftsteller wurde in Las Palmas geboren?', '["Miguel de Unamuno", "Federico García Lorca", "Benito Pérez Galdós", "Camilo José Cela"]'::jsonb, 2, 'Galdós (1843–1920), Autor der „Pérez Galdós“-Romane über Madrid – sein Geburtshaus ist Museum.'),
('island', 7, 'Welcher weltberühmte Tenor stammt aus Las Palmas?', '["Plácido Domingo", "Luciano Pavarotti", "José Carreras", "Alfredo Kraus"]'::jsonb, 3, 'Alfredo Kraus (1927–1999); das Auditorium an der Playa de las Canteras trägt seinen Namen.'),
('island', 7, 'Welcher Felsen in Agaete ist als „Finger Gottes“ bekannt?', '["Dedo de Dios", "Roque Nublo", "Roque Bentayga", "El Fraile"]'::jsonb, 0, 'Die Felsnadel „Dedo de Dios“ – ihre Spitze brach 2005 bei einem Sturm ab.'),
('island', 7, 'Wann griff eine niederländische Flotte Las Palmas an?', '["1499", "1599", "1648", "1704"]'::jsonb, 1, '1599 unter Pieter van der Does – die Stadt wurde geplündert, aber nicht dauerhaft eingenommen.'),
('island', 7, 'Welche Insel ist für ihre Pfeifsprache bekannt?', '["Lanzarote", "El Hierro", "La Gomera", "La Palma"]'::jsonb, 2, 'El Silbo Gomero – eine Pfeifsprache, die über die Schluchten trägt und heute in der Schule gelehrt wird.'),
('island', 7, 'Was war der wichtigste Export im 19. Jahrhundert?', '["Bananen", "Salz", "Wein", "Cochenille-Farbstoff"]'::jsonb, 3, 'Der rote Farbstoff der Schildlaus auf Feigenkakteen – bis synthetische Farben ihn verdrängten.'),
('island', 8, 'Seit wann ist Risco Caído UNESCO-Welterbe?', '["2019", "2013", "2005", "2022"]'::jsonb, 0, 'Im Juli 2019 wurde die Kulturlandschaft „Risco Caído und die heiligen Berge“ zum Welterbe erklärt.'),
('island', 8, 'Wie groß ist das Welterbe-Gebiet?', '["5.000 ha", "18.000 ha", "12.000 ha", "40.000 ha"]'::jsonb, 1, 'Rund 18.000 Hektar – etwa elf Prozent der Inselfläche.'),
('island', 8, 'Was war die „Höhle 6“ von Risco Caído?', '["Ein Kornspeicher", "Ein Gefängnis", "Ein astronomischer Kalender", "Eine Zisterne"]'::jsonb, 2, 'Durch eine Öffnung im Fels fällt Licht zu bestimmten Zeiten auf Markierungen – ein Kalender für Sonne und Mond.'),
('island', 8, 'Welcher Fels gehört zu den „heiligen Bergen“?', '["Roque Nublo", "Pico de las Nieves", "Montaña de Arucas", "Roque Bentayga"]'::jsonb, 3, 'Roque Bentayga war Zeremonienplatz; der Roque Nublo ist Wahrzeichen, aber nicht Teil des Welterbes.'),
('island', 8, 'In welchen Gemeinden liegt das Welterbe?', '["Artenara, Tejeda, Agaete, Gáldar", "Maspalomas, Mogán, San Bartolomé", "Las Palmas, Telde, Ingenio", "Agüimes, Santa Lucía, Temisas"]'::jsonb, 0, 'Vier Gemeinden im Nordwesten und Zentrum, rund um die Caldera de Tejeda.'),
('island', 8, 'Wie alt sind die ältesten Spuren der Ureinwohner?', '["Etwa 500 Jahre", "Etwa 2.000 Jahre", "Etwa 10.000 Jahre", "Etwa 50.000 Jahre"]'::jsonb, 1, 'Man geht von rund 2.000 Jahren aus – die Besiedlung begann etwa um Christi Geburt.'),
('island', 8, 'Was bedeutet das Wort „Guanarteme“?', '["Häuptling", "Priester", "König", "Krieger"]'::jsonb, 2, 'Guanarteme war der Titel der Herrscher von Gáldar und Telde – also „König“ der Inselhälften.'),
('island', 8, 'Wie hieß Gran Canaria bei den Römern?', '["Insula Fortunata", "Nivaria", "Tamarán", "Canaria"]'::jsonb, 3, 'Plinius nannte die Insel „Canaria“ – vermutlich wegen der großen Hunde (canes).'),
('island', 8, 'Welche Kanareninsel heißt „die Schöne“?', '["La Palma", "La Gomera", "Teneriffa", "El Hierro"]'::jsonb, 0, 'La Palma, auch „Isla Bonita“ – mit der Caldera de Taburiente.'),
('island', 8, 'Was ist der „Pico de las Nieves“ wörtlich?', '["Berg der Wolken", "Schneegipfel", "Steinberg", "Berg der Winde"]'::jsonb, 1, '„Schnee“-Gipfel – hier lag im Winter am meisten Schnee, der im 17. Jahrhundert in Schneegruben gesammelt und nach Las Palmas gebracht wurde.'),
('island', 8, 'Wie hieß der letzte Vulkanausbruch der Insel?', '["Cumbre Vieja", "Teide", "Bandama", "Timanfaya"]'::jsonb, 2, 'Der Ausbruch, der die Caldera de Bandama formte, liegt rund 2.000 Jahre zurück.'),
('island', 8, 'Welcher Ort ist für seine Töpferei bekannt?', '["Arinaga", "Temisas", "Maspalomas", "La Atalaya de Santa Brígida"]'::jsonb, 3, 'In La Atalaya wird bis heute ohne Töpferscheibe gearbeitet – eine Tradition aus der Zeit vor der Eroberung.'),
('island', 9, 'Welcher Fink lebt nur im Kiefernwald von Inagua?', '["Gran-Canaria-Teydefink", "Buchfink", "Grünfink", "Stieglitz"]'::jsonb, 0, 'Der Blaufink (Gran-Canaria-Teydefink) brütet fast nur in den Kiefernwäldern von Inagua – Bestand im niedrigen dreistelligen Bereich.'),
('island', 9, 'Wie heißt der Lorbeerwald der feuchten Nordhänge?', '["Monteverde", "Laurisilva", "Pinar", "Fayal"]'::jsonb, 1, 'Laurisilva – ein Relikt des Tertiärs, das auf den Kanaren die Eiszeit überlebt hat.'),
('island', 9, 'Welcher Baum ist das Symbol der kanarischen Flora?', '["Zypresse", "Olivenbaum", "Drachenbaum", "Kastanie"]'::jsonb, 2, 'Dracaena draco – sein rotes Harz galt als „Drachenblut“ und wurde als Heilmittel gehandelt.'),
('island', 9, 'Woher stammt der Feigenkaktus der Insel?', '["Aus Indien", "Aus Marokko", "Aus Spanien", "Aus Mexiko"]'::jsonb, 3, 'Er kam nach 1492 aus Amerika – und mit ihm die Cochenille-Schildlaus.'),
('island', 9, 'Welche Wolkenformation liegt oft über dem Norden?', '["Mar de nubes", "Calima", "Bruma seca", "Nube baja"]'::jsonb, 0, 'Ein „Meer aus Wolken“, das sich am Passat staut und den Norden feucht hält.'),
('island', 9, 'Wie schützt sich die Kanarische Kiefer gegen Feuer?', '["Sie wächst nur im Regen", "Dicke Rinde", "Ihre Nadeln brennen nicht", "Sie speichert Wasser"]'::jsonb, 1, 'Die dicke Rinde isoliert die Knospen; nach einem Brand treibt der Baum aus dem Stamm neu aus.'),
('island', 9, 'Wann ist die beste Zeit zum Wandern im Bergland?', '["Juli und August", "Dezember und Januar", "Frühling und Herbst", "Nur nach Regen"]'::jsonb, 2, 'Frühling und Herbst – im Sommer ist es im Süden sehr heiß, im Winter kann es oben kalt und windig sein.'),
('island', 9, 'Was ist ein „tajinaste“?', '["Ein Vogel", "Ein Tanz", "Ein Werkzeug", "Eine Pflanze mit Blütenkerze"]'::jsonb, 3, 'Natternkopf-Arten (Echium) mit hohen Blütenständen – auf Gran Canaria mehrere endemische Arten.'),
('island', 9, 'Warum gibt es so viele endemische Arten?', '["Weil die Insel lange isoliert war", "Weil die Insel groß ist", "Weil es viel regnet", "Weil es keine Menschen gab"]'::jsonb, 0, 'Isolation über Millionen Jahre bei großer Höhenvielfalt – daraus entstanden eigene Arten.'),
('island', 9, 'Welche Gefahr bedroht die Wälder im Sommer am meisten?', '["Schnee", "Waldbrand", "Sturmflut", "Erdbeben"]'::jsonb, 1, 'Dürre und Hitze machen die Kiefernwälder anfällig; die Feuerwehr rechnet mit jedem Sommer.'),
('island', 9, 'Wie hoch reicht der Kiefernwald?', '["Bis 400 m", "Bis 1.000 m", "Bis 2.000 m", "Bis zum Gipfel"]'::jsonb, 2, 'Von etwa 800 bis knapp 2.000 Metern – darüber nur noch Ginster und Fels.'),
('island', 9, 'Welches Tier der Küste kann man vom Boot aus sehen?', '["Seeotter", "Pinguine", "Robben", "Wale und Delfine"]'::jsonb, 3, 'Vor der Südwestküste leben Große Tümmler und Rundkopfdelfine ganzjährig.'),
('island', 10, 'Wie heißt das kanarische Dessert aus Eigelb, Mandeln und Sirup?', '["Bienmesabe", "Flan", "Tarta de Santiago", "Turrón"]'::jsonb, 0, 'Bienmesabe – „schmeckt mir gut“ – wird kalt gelöffelt oder als Brotaufstrich gegessen.'),
('island', 10, 'Welcher Eintopf aus Fisch ist typisch kanarisch?', '["Paella", "Sancocho", "Fabada", "Cocido"]'::jsonb, 1, 'Sancocho – mit Salzwasserfisch, Kartoffeln und Mojo; auf den Kanaren ein Festtagsessen.'),
('island', 10, 'Was ist „ropa vieja“?', '["Ein Kleidungsstück", "Ein Nachtisch", "Ein Eintopf mit Fleisch und Kichererbsen", "Ein Salat"]'::jsonb, 2, 'Wörtlich „alte Kleider“ – ein Eintopf aus Rind- oder Schweinefleisch, Kichererbsen und Tomate.'),
('island', 10, 'Was ist „ron miel“?', '["Ein Wein", "Ein Kuchen", "Ein Käse", "Rum mit Honig"]'::jsonb, 3, 'Honigrum – ein Likör aus Rum und kanarischem Honig, sehr süß.'),
('island', 10, 'Von welcher Insel kommt „almogrote“?', '["La Gomera", "Gran Canaria", "Lanzarote", "El Hierro"]'::jsonb, 0, 'Ein Aufstrich aus gereiftem Käse, Paprika und Olivenöl – klassisch von La Gomera.'),
('island', 10, 'Welche Rebsorte ist typisch für die kanarischen Rotweine?', '["Tempranillo", "Listán Negro", "Rioja", "Merlot"]'::jsonb, 1, 'Listán Negro – eine alte, fast nur hier angebaute Sorte.'),
('island', 10, 'Was ist „miel de palma“?', '["Palmzucker", "Palmwein", "Palmhonig", "Palmöl"]'::jsonb, 2, 'Ein Sirup, der aus dem Saft der Kanarischen Palme gekocht wird – vor allem auf La Gomera.'),
('island', 10, 'Wann feiert man den Karneval auf der Insel?', '["Im Dezember", "Im Juli", "Im Oktober", "Im Februar"]'::jsonb, 3, 'Der Karneval liegt im Februar, die großen Umzüge finden in Las Palmas statt.'),
('island', 10, 'Was aßen die Ureinwohner als Grundnahrungsmittel?', '["Gofio", "Reis", "Kartoffeln", "Mais"]'::jsonb, 0, 'Gofio aus geröstetem Weizen oder Gerste – Kartoffeln und Mais kamen erst nach 1492.'),
('island', 10, 'Was ist „queso de flor“?', '["Ein Blumenstrauß", "Käse mit Distelblüte", "Ein Kuchen", "Ein Likör"]'::jsonb, 1, 'Der Labersatz stammt aus der Blüte der Artischockendistel – daher der Name und der feine Geschmack.'),
('island', 10, 'Welcher Fisch ist auf den Kanaren eine Spezialität?', '["Hering", "Kabeljau", "Vieja", "Lachs"]'::jsonb, 2, 'Die Vieja (Papageifisch) – meist gebraten mit Mojo, manchmal mit Knochen serviert.'),
('island', 10, 'Was trinkt man traditionell zum Kaffee dazu?', '["Ein Glas Milch", "Tee", "Ein Bier", "Ein kleiner Schnaps"]'::jsonb, 3, 'Ein „chupito“ – oft Ron miel oder ein Kräuterschnaps, häufig aufs Haus.'),
('island', 11, 'Wie viele große Eruptionsphasen durchlief die Insel?', '["Drei", "Zwei", "Fünf", "Sieben"]'::jsonb, 0, 'Ciclo I (alte Basalte), Ciclo II (Roque-Nublo-Formation) und Ciclo III (die jüngeren Vulkanbauten im Norden).'),
('island', 11, 'Welcher Berg gab der zweiten Eruptionsphase den Namen?', '["Teide", "Roque Nublo", "Bandama", "Pico de las Nieves"]'::jsonb, 1, 'Die „Roque-Nublo-Formation“ prägt weite Teile des Inselinneren – mit mächtigen Brekzien und Lavaströmen.'),
('island', 11, 'Wie breit ist die Caldera de Tejeda?', '["5 km", "30 km", "15 km", "50 km"]'::jsonb, 2, 'Rund 15 Kilometer – ein eingebrochener Vulkankessel, in dem Tejeda und Artenara liegen.'),
('island', 11, 'Was ist die Caldera de Bandama geologisch?', '["Ein Karstloch", "Ein Schildvulkan", "Ein Kratersee", "Ein Maar"]'::jsonb, 3, 'Ein Maar – ein Explosionskrater, entstanden als Magma auf Grundwasser traf.'),
('island', 11, 'Wie entsteht ein Maar?', '["Magma trifft auf Grundwasser und verdampft explosionsartig", "Durch Erosion", "Durch ein Erdbeben", "Durch einen Meteoriten"]'::jsonb, 0, 'Das Wasser verdampft schlagartig, der Druck sprengt einen Trichter – daher die steilen Wände.'),
('island', 11, 'Wo liegen die ältesten Gesteine der Insel?', '["Im Norden", "Im Südwesten", "Im Osten", "Auf dem Gipfel"]'::jsonb, 1, 'Im Südwesten um La Aldea und Güigüí – dort ist die Insel am ältesten.'),
('island', 11, 'Wie viele Mikroklimazonen hat Gran Canaria?', '["4", "7", "14", "21"]'::jsonb, 2, '14 – deshalb der Beiname „Kontinent im Miniaturformat“.'),
('island', 11, 'Welche Winde bestimmen das Wetter?', '["Mistral", "Bora", "Scirocco", "Passatwinde"]'::jsonb, 3, 'Die Passatwinde (alisios) wehen aus Nordost und teilen die Insel in feuchten Norden und trockenen Süden.'),
('island', 11, 'Wie lang ist die Küstenlinie der Insel?', '["236 km", "120 km", "380 km", "500 km"]'::jsonb, 0, 'Rund 236 Kilometer – bei nur 50 Kilometern Durchmesser.'),
('island', 11, 'Wie weit ist es von Gran Canaria bis nach Marokko?', '["80 km", "210 km", "400 km", "700 km"]'::jsonb, 1, 'Etwa 210 Kilometer bis zur afrikanischen Küste.'),
('island', 11, 'Was ist ein „malpaís“?', '["Ein schlechtes Land", "Ein Sumpf", "Ein Lavafeld", "Ein Weinberg"]'::jsonb, 2, 'Wörtlich „schlechtes Land“ – eine raue Lavalandschaft, auf der kaum etwas wächst.'),
('island', 11, 'Warum gibt es auf der Insel keine echten Flüsse?', '["Es regnet nicht", "Das Wasser verdunstet sofort", "Die Täler sind zu steil", "Das Wasser versickert im porösen Vulkangestein"]'::jsonb, 3, 'Das Regenwasser verschwindet im Gestein und tritt weiter unten wieder aus – deshalb die vielen Trockentäler.'),
('island', 12, 'Seit wann haben die Kanaren eine eigene Autonomie?', '["1982", "1978", "1931", "1992"]'::jsonb, 0, 'Das Autonomiestatut trat 1982 in Kraft; die erste Regionalregierung wurde 1983 gewählt.'),
('island', 12, 'Wann trat Spanien der Europäischen Gemeinschaft bei?', '["1975", "1986", "1992", "2004"]'::jsonb, 1, '1986 – die Kanaren kamen mit einem Sonderstatus dazu, der bis heute gilt.'),
('island', 12, 'Welche Steuer gilt auf den Kanaren statt der Mehrwertsteuer?', '["IVA", "IRPF", "IGIC", "ITP"]'::jsonb, 2, 'Der IGIC (Impuesto General Indirecto Canario) – niedriger als die spanische IVA.'),
